from decimal import Decimal, ROUND_HALF_UP, localcontext


_CENT = Decimal("0.01")


def _decimal(value) -> Decimal:
    if value is None or value == "":
        return Decimal(0)
    if isinstance(value, Decimal):
        return value
    return Decimal(str(value))


def _precision(*values: Decimal) -> int:
    precision = 50
    for value in values:
        if value:
            digits = value.as_tuple().digits
            precision += len(digits) + max(0, value.adjusted())
    return precision


def _round_cents(value: Decimal) -> Decimal:
    with localcontext() as context:
        context.prec = _precision(value)
        return value.quantize(_CENT, rounding=ROUND_HALF_UP)


def recompute(order: dict, lines: list[dict]) -> tuple[dict, list[dict], list]:
    new_order = dict(order)
    new_lines = [dict(line) for line in lines]

    if order.get("DEL_FLG") == "Y" or order.get("STAT_CD") == "X":
        return new_order, new_lines, []

    quantities = [_decimal(line.get("QTY")) for line in lines if line.get("DEL_FLG") != "Y"]
    prices = [_decimal(line.get("UNIT_PRC")) for line in lines if line.get("DEL_FLG") != "Y"]
    discount = _decimal(order.get("DISC_PCT"))

    with localcontext() as context:
        context.prec = _precision(*(quantities + prices + [discount])) + len(lines) + 10

        total = Decimal(0)
        for line, quantity, price in zip(
            (line for line in new_lines if line.get("DEL_FLG") != "Y"),
            quantities,
            prices,
        ):
            extension = (quantity * price).quantize(
                _CENT, rounding=ROUND_HALF_UP
            )
            line["EXT_AMT"] = float(extension)
            total += extension

        discounted = (total * (Decimal(100) - discount) / Decimal(100)).quantize(
            _CENT, rounding=ROUND_HALF_UP
        )

    new_order["TOT_AMT"] = float(discounted)

    audits = []
    if _decimal(order.get("TOT_AMT")) != discounted:
        audits.append(("ORD_RETOTAL", order.get("ORD_ID")))

    return new_order, new_lines, audits
